import {newId} from './archive.js';
import {Chess} from './vendor/chess.js';
import {Engine,terminal} from './analysis.js';
import {readAll,putRecord,errorPositions,mirrorFen,THEMES} from './archive.js';
import {drawBoard,choosePiece} from './mini-board.js';
import {strategicHint,briefComment} from './brief-coach.js';
import {classify} from './analysis.js';
const $=id=>document.getElementById(id),engine=new Engine(s=>$('practiceStatus').textContent=s);let errors=[],index=0,chess,fen='',base=null,selected=null,flipped=false,busy=false,solved=false,assisted=false,token=0;
function render(){if(chess)drawBoard($('practiceBoard'),chess,{selected,flipped,disabled:busy||solved});['practiceMode','practiceReset','practiceNext','practiceHint','practiceSolution'].forEach(id=>$(id).disabled=busy)}
async function counts(){const attempts=await readAll('attempts');$('practiceCounts').textContent=`${attempts.length} tentativi registrati · ${attempts.filter(a=>a.success&&!a.assisted).length} riusciti senza soluzione mostrata.`}
async function load(){const id=++token;busy=true;solved=false;selected=null;assisted=false;base=null;const e=errors[index];fen=$('practiceMode').value==='similar'?mirrorFen(e.fen):e.fen;chess=new Chess(fen);flipped=chess.turn()==='b';$('practiceTheme').textContent=THEMES[e.theme];$('practiceContext').textContent=`Posizione ${index+1} di ${errors.length} · muove il ${chess.turn()==='w'?'Bianco':'Nero'}. ${$('practiceMode').value==='similar'?'Stesso problema strategico, con colori e traverse invertiti.':'È la posizione prima di una tua mossa da rivedere.'}`;$('practiceFeedback').textContent='Preparazione della posizione…';render();try{const r=await engine.evaluate(fen,'deep');if(id!==token)return;base=r;$('practiceFeedback').textContent='Scegli la tua mossa. Il piano lo costruisci tu.'}catch(e){$('practiceFeedback').textContent=e.message}finally{busy=false;render();counts().catch(()=>{})}}
$('practiceBoard').onclick=async e=>{if(busy||solved||!base)return;const b=e.target.closest('[data-sq]');if(!b)return;const sq=b.dataset.sq,p=chess.get(sq),candidates=selected?chess.moves({square:selected,verbose:true}).filter(m=>m.to===sq):[];if(!candidates.length){selected=p?.color===chess.turn()?sq:null;render();return}let promotion;if(candidates.some(m=>m.promotion)){promotion=await choosePiece(chess.turn());if(!promotion)return}busy=true;const from=selected,m=chess.move({from,to:sq,promotion:promotion||'q'});selected=null;render();try{const after=terminal(chess)||await engine.evaluate(chess.fen(),'deep'),uci=m.from+m.to+(m.promotion||''),side=m.color==='w'?1:-1,grade=classify({before:base,after,side,uci,book:false});const success=uci===base.lines?.[0]?.pv[0]||(grade.loss<=.02&&(base.cp-after.cp)*side<=50);solved=true;$('practiceFeedback').textContent=(success?'Sì, questa scelta funziona. ':'Questa scelta è da rivedere. ')+briefComment(m,base,after,grade,'quiet');await putRecord({id:newId(),position:errors[index].id,theme:errors[index].theme,mode:$('practiceMode').value,success,assisted,at:Date.now()},'attempts');await counts()}catch(err){$('practiceFeedback').textContent=err.message;solved=true}finally{busy=false;render()}};
$('practiceMode').onchange=load;$('practiceReset').onclick=()=>{chess=new Chess(fen);selected=null;solved=false;$('practiceFeedback').textContent='Riprova: prima controlla la risposta dell’avversario.';render()};$('practiceNext').onclick=()=>{index=(index+1)%errors.length;load()};$('practiceFlip').onclick=()=>{flipped=!flipped;render()};$('practiceHint').onclick=()=>{$('practiceFeedback').textContent=strategicHint(new Chess(fen))};$('practiceSolution').onclick=()=>{const u=base?.lines?.[0]?.pv[0];if(!u)return;assisted=true;const c=new Chess(fen),m=c.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});$('practiceFeedback').textContent=`Una soluzione trovata è ${m.san} (${m.from} → ${m.to}). Riparti dalla posizione e chiediti che cosa cambia.`};
(async()=>{try{errors=errorPositions(await readAll());$('practiceEmpty').hidden=errors.length>0;$('practiceWorkspace').hidden=!errors.length;if(errors.length)await load()}catch(e){$('practiceStatus').textContent=e.message}})();
